				api.GetSilentAimHit = function(maxDistance, raycastParams, rayOrigin)
					local currentCamera = workspace.CurrentCamera
					if not currentCamera or type(maxDistance) ~= "number" or maxDistance <= 0 then
						return
					end
					rayOrigin = rayOrigin or currentCamera.CFrame.Position
					local viewportCenter = currentCamera.ViewportSize / 2
					local bestScreenDistanceSquared = settings.SAIMRadius ^ 2
					local bestHitResult = nil

					for _, candidatePlayer in ipairs(hubState.PlayerList) do
						if api.IsSilentAimTarget(candidatePlayer) then
							local targetCharacter, targetPart, targetHumanoid = api.Char(candidatePlayer)

							if targetPart and targetHumanoid and targetHumanoid.Health > 0 then
								local screenPoint, isOnScreen = currentCamera:WorldToViewportPoint(targetPart.Position)

								if isOnScreen then
									local screenDeltaX = screenPoint.X - viewportCenter.X
									local screenDeltaY = screenPoint.Y - viewportCenter.Y
									local screenDistanceSquared = screenDeltaX * screenDeltaX + screenDeltaY * screenDeltaY
									local targetOffset = targetPart.Position - rayOrigin
									local targetDistance = targetOffset.Magnitude

									if screenDistanceSquared <= bestScreenDistanceSquared and targetDistance > 0.001 and targetDistance <= maxDistance + targetPart.Size.Magnitude / 2 then
										local raycastResult = workspace:Raycast(rayOrigin, targetOffset.Unit * math.min(maxDistance, targetDistance + targetPart.Size.Magnitude / 2), raycastParams)

										if raycastResult and raycastResult.Instance:IsDescendantOf(targetCharacter) then
											bestScreenDistanceSquared = screenDistanceSquared
											bestHitResult = raycastResult
										end
									end
								end
							end
						end
					end

					return bestHitResult
				end

