		api.SelectServerHopServer = function(servers)
			if #servers == 0 then
				return
			end

			if settings.ServerHopSort == "Closest Datacenter" or settings.ServerHopSort == "Lowest Ping" or settings.ServerHopSort == "Random" then
				return servers[math.random(1, #servers)]
			end

			table.sort(servers, function(server, serverOptions)
				local playing, playing2

				if settings.ServerHopSort == "Lowest Players" then
					playing = server.Playing
					playing2 = serverOptions.Playing
				elseif settings.ServerHopSort == "Highest Players" then
					playing = -server.Playing
					playing2 = -serverOptions.Playing
				elseif settings.ServerHopSort == "Highest FPS" then
					playing = -(server.FPS or 0)
					playing2 = -(serverOptions.FPS or 0)
				else
					playing = server.Ping or math.huge
					playing2 = serverOptions.Ping or math.huge
				end

				if playing == playing2 then
					return server.Id < serverOptions.Id
				end
				return playing < playing2
			end)

			return servers[1]
		end

