							blobmanUtils.LoopLock(inputValue, targetList)
						end
					else
						processLocalHelper9 = blobmanUtils.Lock
					end

					runSelectedPlayerMethod("Blob_Lock", processLocalHelper9)
				elseif blobMethod == "Kick" and not methodName then
					local loopKick

					if method then
						loopKick = blobmanUtils.LoopKick
					else
						loopKick = blobmanUtils.Kick
					end

					runSelectedPlayerMethod("Blob_Kick", loopKick)
				end

				return
			end

			local targetMethods = hubState.TargetMethods
			local localValue310, localValue311 = api.Char(player)

			if targetMethods["Remove Invisibility"] and localValue311 then
