				else
					booleanFlag70 = not methodName and not method
				end
			else
				booleanFlag70 = kick
			end

			if booleanFlag70 then
				runSelectedPlayerMethod("Kick", api.Void)
			end

			if targetMethods.Kill then
				runSelectedPlayerMethod("Kill", api.Kill)
			end

			if targetMethods.Void then
				runSelectedPlayerMethod("Void", api.Void)
			end

			if targetMethods["Remove Gucci"] then
				runSelectedPlayerMethod("Remove Gucci", api.RemoveGucci)
			end

			if targetMethods["Destroy Food"] then
				runSelectedPlayerMethod("Destroy Food", api.EatAntiInput)
