					return
				end
				flag13 = true

				task.spawn(function()
					local FoodHamburger = nil
					local targetInstance40 = nil
					local localValue422 = nil
					local booleanFlag81 = false

					local function processCharacterState4()
						if localValue422 and targetInstance40 and targetInstance40.Parent and localPlayer.Character and targetInstance40:IsDescendantOf(localPlayer.Character) then
							api.Teleport(targetInstance40, localValue422)
						end

						localValue422 = nil
						targetInstance40 = nil

						if booleanFlag81 then
							hubState.States.Owning = false
							booleanFlag81 = false
						end

						if FoodHamburger then
							hubState.ToyAuraReserved[FoodHamburger] = nil
							api.DestroyToy(FoodHamburger)
							FoodHamburger = nil
						end
					end

					local ok, result = pcall(function()
						if api.IsBarrierBroken() then
							if flag12 then
								sendHubNotification("Barrier is already broken!")

								if toggles.DeleteBarriers then
									toggles.DeleteBarriers:SetValue(true)
								end
							end

							return
						end

						while true do
							if flag12 and task.wait() then
								local localValue423, targetInstance41, humanoid83 = api.Char()

								if not (targetInstance41 and humanoid83 and humanoid83.Health > 0) or hubState.States.Owning then
									continue
								else
									local function processHumanoidState2()
										return flag12 and localPlayer.Character == localValue423 and targetInstance41.Parent and humanoid83.Health > 0
									end

									FoodHamburger = api.SpawnToy("FoodHamburger", nil, 4, true)

									if not FoodHamburger then
										continue
									else
										local holdPart = FoodHamburger:WaitForChild("HoldPart", 0.35)
										local holdItemRemoteFunction = holdPart and holdPart:WaitForChild("HoldItemRemoteFunction", 0.35)
										local rigidConstraint = holdItemRemoteFunction and holdPart:WaitForChild("RigidConstraint", 0.35)

										if not (processHumanoidState2() and holdItemRemoteFunction and rigidConstraint) then
											processCharacterState4()
											continue
										else
											while processHumanoidState2() and hubState.States.Owning do
												task.wait()
											end

											if not processHumanoidState2() then
												processCharacterState4()
												break
											else
												local cFrame2 = targetInstance41.CFrame
												targetInstance40 = targetInstance41
												localValue422 = cFrame2
												booleanFlag81 = true
												hubState.States.Owning = true
												api.Teleport(targetInstance41, workspace.Waypoints.BlueHouse)
												local numericValue201 = os.clock()

												while true do
													task.wait()
													if not (not processHumanoidState2() or localPlayer.InPlot.Value or os.clock() - numericValue201 > 0.7) then
														continue
													end
													break
												end

												if not processHumanoidState2() or not localPlayer.InPlot.Value then
													processCharacterState4()
													continue
												else
													local targetInstance42 = FoodHamburger

													task.spawn(function()
														if processHumanoidState2() and targetInstance42.Parent and holdItemRemoteFunction.Parent then
															pcall(function()
																holdItemRemoteFunction:InvokeServer(targetInstance42, localValue423)
															end)
														end
													end)

													local numericValue202 = os.clock()

													while true do
														task.wait()
														if not (not processHumanoidState2() or not rigidConstraint.Parent or rigidConstraint.Attachment1 or os.clock() - numericValue202 > 0.7) then
															continue
														end
														break
													end

													if not processHumanoidState2() or not rigidConstraint.Parent or not rigidConstraint.Attachment1 then
														processCharacterState4()
														continue
													else
														api.DestroyToy(FoodHamburger)
														hubState.ToyAuraReserved[FoodHamburger] = nil
														FoodHamburger = nil
														task.wait(0.5)
														processCharacterState4()

														if not processHumanoidState2() then
															break
														else
															task.wait(1)

															if flag12 and api.IsBarrierBroken() then
																if flag12 then
																	sendHubNotification("Barrier has been broken!")

																	if toggles.DeleteBarriers then
																		toggles.DeleteBarriers:SetValue(true)
																	end
																end

																break
															else
																continue
															end
														end
													end
												end
											end
										end
									end
								end
							end

							break
						end
					end)

					processCharacterState4()
					flag13 = false

					if not ok then
						warn("[House Barrier] " .. tostring(result))
