			tableValue64.Default = localValue425
			tableValue64.Min = min
			tableValue64.Max = max
			tableValue64.Compact = true
			tableValue64.Rounding = rounding

			tableValue64.Callback = function(value)
				if not callbackOption then
					toysAuraSettings[selectedValue] = value
					return
				end
				local positionVector5 = toysAuraSettings[selectedValue]
				local x

				if callbackOption == "X" then
					x = value
				else
					x = positionVector5.X
				end

				local y

				if callbackOption == "Y" then
					y = value
				else
					y = positionVector5.Y
				end

				if callbackOption ~= "Z" then
					value = positionVector5.Z
				end

				local localValue426 = toysAuraSettings
				local localValue427 = selectedValue
				local cframe

				if selectedValue == "Offset" then
