		local function spawnNinjaShuriken2(spawnCFrame)
			local targetInstance44 = spawnCFrame or api.GetTarget()
			if not targetInstance44 or not targetInstance44:IsA("BasePart") then
				return
			end
			local cframe

			if n36 == 1 then
				cframe = CFrame.new(1e15, 1e15, 1e15)
			else
				cframe = CFrame.new(0, -2.3e9, 0)
			end

			local NinjaShuriken = api.SpawnToy("NinjaShuriken")
			local stickyPart = NinjaShuriken and NinjaShuriken:WaitForChild("StickyPart", 0.5)
			local stickyWeld = stickyPart and stickyPart:WaitForChild("StickyWeld", 0.5)
			if not stickyWeld then
				return api.DestroyToy(NinjaShuriken)
			end

			if not api.SNO(stickyPart) then
				return api.DestroyToy(NinjaShuriken)
			end
			api.TrackBrokenPart(targetInstance44, stickyWeld)
			n37 += 1
			local stringValue35 = "BreakPartAffectsYou" .. n37

			api.SetRuntimeConnection(stringValue35, stickyWeld:GetPropertyChangedSignal("Enabled"), true, function()
				if stickyWeld.Enabled ~= enabled then
					stickyWeld.Enabled = enabled
				end
			end)

			api.SetRuntimeConnection(stringValue35 .. "Cleanup", stickyWeld.Destroying, true, function()
				obj[stickyWeld] = nil
				api.UntrackBrokenPart(targetInstance44, stickyWeld)
				api.SetRuntimeConnection(stringValue35, nil, false)
				api.SetRuntimeConnection(stringValue35 .. "Cleanup", nil, false)
			end)

			local localValue435 = enabled
			obj[stickyWeld] = true
			stickyWeld.Enabled = localValue435
			remoteEvents.StickyPartEvent:FireServer(stickyPart, targetInstance44, cframe)
		end

