	do
		local Graphics = hubTabs.Visual:AddRightGroupbox("Graphics", "file-image")
		local n36 = 0
		local n37 = 0.004
		local n38 = 128

		local function waitUntilElapsed(enabled)
			if os.clock() - enabled < n37 then
				return enabled
			end
			RunService.Heartbeat:Wait()
			return os.clock()
		end

		local function updateVisualState2(visualObject)
			local numericValue204 = os.clock()

			for i = #hubState.WaterParts, 1, -1 do
				if visualObject ~= n36 then
					return false
				end
				local localValue445 = hubState.WaterParts[i]
				local targetPart26 = localValue445[1]
				local transparency = localValue445[2]

				if targetPart26 and targetPart26.Parent then
					local value = toggles.WaterWalk and toggles.WaterWalk.Value

					if value and transparency ~= 1 then
						transparency = 0.5
					end

					targetPart26.Transparency = transparency

					if not value and hubState.WaterPartStates[targetPart26] then
						targetPart26.CanCollide = hubState.WaterPartStates[targetPart26][1]
						hubState.WaterPartStates[targetPart26] = nil
					end
				end

				hubState.WaterParts[i] = nil
				numericValue204 = waitUntilElapsed(numericValue204)
			end

			for i = #hubState.WaterRegions, 1, -1 do
				if visualObject ~= n36 then
					return false
				end
				terrain:FillRegion(hubState.WaterRegions[i], 4, Enum.Material.Air)
				hubState.WaterRegions[i] = nil
				numericValue204 = waitUntilElapsed(numericValue204)
			end

			table.clear(hubState.WaterRegions)
			table.clear(hubState.WaterParts)
			return true
		end

		local function createAlignedRegion(target, targetCFrame, option, force)
			local targetPart27 = Region3.new(target, targetCFrame):ExpandToGrid(4)
			local positionVector6 = targetPart27.CFrame.Position - targetPart27.Size / 2
			local positionVector7 = targetPart27.CFrame.Position + targetPart27.Size / 2
			local x = positionVector6.X

			while x < positionVector7.X do
				local numericValue205 = math.min(x + n38, positionVector7.X)
				local y = positionVector6.Y
				local exitTo = nil

				while true do
					if not (y < positionVector7.Y) then
						exitTo = 1
						break
					else
						local numericValue206 = math.min(y + n38, positionVector7.Y)
						local z = positionVector6.Z
						local exitTo2 = nil

						while true do
							if not (z < positionVector7.Z) then
								exitTo2 = 1
								break
							else
								if option == n36 then
									local numericValue207 = math.min(z + n38, positionVector7.Z)
									local localValue446 = Region3.new(Vector3.new(x, y, z), Vector3.new(numericValue205, numericValue206, numericValue207))
									hubState.WaterRegions[#hubState.WaterRegions + 1] = localValue446
									terrain:FillRegion(localValue446, 4, Enum.Material.Water)
									force = waitUntilElapsed(force)
									z = numericValue207
									continue
								end

								break
							end
						end

						if exitTo2 == 1 then
							y = numericValue206
							continue
						end
						break
					end
				end

				if exitTo == 1 then
					x = numericValue205
					continue
				end
				return force, false
			end

			return force, true
		end

		local function cacheCharacterCollisions2(target)
			n36 += 1
			local localValue447 = n36

			task.spawn(function()
				if not updateVisualState2(localValue447) or not target then
					return
				end
				local objectModel = workspace.Map.AlwaysHereTweenedObjects.Ocean.Object.ObjectModel
				local vector = Vector3.new(0, settings.WaterYOffset, 0)
				local tableValue67 = {}

				for _, v21 in ipairs(objectModel:QueryDescendants("BasePart")) do
					local tableValue68 = hubState.WaterPartStates[v21]

					if not tableValue68 then
						if v21.Transparency == 1 then
							continue
						end
						tableValue68 = { v21.CanCollide, v21.Transparency }
						hubState.WaterPartStates[v21] = tableValue68
					end

					if tableValue68[2] ~= 1 then
						tableValue67[#tableValue67 + 1] = { v21, tableValue68[2], v21.Position - v21.Size / 2 + vector, v21.Position + v21.Size / 2 + vector }
					end
				end

				for _, v21 in ipairs(tableValue67) do
					local v22 = v21[1]

					if v22.Parent then
						hubState.WaterParts[#hubState.WaterParts + 1] = { v22, v21[2] }
						v22.Transparency = 1
					end
				end

				local numericValue208 = os.clock()

				for _, v21 in ipairs(tableValue67) do
					if localValue447 ~= n36 then
						return
					end
					local v22, localValue448 = createAlignedRegion(v21[3], v21[4], localValue447, numericValue208)
					if not localValue448 then
						return
					end
					numericValue208 = v22
				end
			end)
		end

		local tbl16 = {}

		local function cleanupInstanceConnection3(humanoidArgument, humanoid)
			if tbl16.Humanoid ~= humanoid or not humanoidArgument then
				if tbl16.Connection then
					tbl16.Connection:Disconnect()
				end

				if tbl16.Humanoid and tbl16.Humanoid.Parent and tbl16.Enabled ~= nil then
					tbl16.Humanoid:SetStateEnabled(Enum.HumanoidStateType.Swimming, tbl16.Enabled)
				end

				table.clear(tbl16)
			end

			if not humanoidArgument or not humanoid then
				return
			end

			if not tbl16.Humanoid then
				tbl16.Humanoid = humanoid
				tbl16.Enabled = humanoid:GetStateEnabled(Enum.HumanoidStateType.Swimming)

				tbl16.Connection = humanoid.StateChanged:Connect(function(old, new)
					if new == Enum.HumanoidStateType.Swimming and featureToggles.NonSwimmableWater and toggles.CustomWaterT.Value then
						humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
					end
				end)
			end

			humanoid:SetStateEnabled(Enum.HumanoidStateType.Swimming, false)
			local swimming = Enum.HumanoidStateType.Swimming

			if humanoid:GetState() == swimming then
				humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
			end
		end

		api.RestoreWaterSettings = function()
			cacheCharacterCollisions2(false)
			cleanupInstanceConnection3(false)

			for k, waterPartState in pairs(hubState.WaterPartStates) do
				if k.Parent then
					local localValue449 = waterPartState[2]
					k.CanCollide = waterPartState[1]
					k.Transparency = localValue449
				end
			end

			table.clear(hubState.WaterPartStates)

			for k, waterSetting in pairs(hubState.WaterSettings) do
				terrain[k] = waterSetting
			end
		end

		Graphics:AddDivider("Water")

		Graphics:AddToggle("CustomWaterT", {
