	do
		local Whitelist = hubTabs.Lists:AddLeftGroupbox("Whitelist", "shield-check")
		local v20 = api.CreatePlayerDropdown(Whitelist, "Whitelist", hubState.Whitelisted)

		v20:OnChanged(function()
			if featureToggles.SilentAim then
				api.RefreshSilentAim()
			end
		end)

		local tbl16 = {}
		local friendStatusChanged = nil

		pcall(function()
			friendStatusChanged = localPlayer.FriendStatusChanged
		end)

		local function updateFriendWhitelist(player, playerOption)
			if flag11 or not featureToggles.AutoWhitelistFriends or player == localPlayer or player.Parent ~= Players or api.IsProtectedPlayer(player) then
				return
			end
			local booleanFlag87 = v20.Value[player] == true

			if playerOption then
				if booleanFlag87 then
					return
				end
				tbl16[player.UserId] = true
			else
				if not tbl16[player.UserId] then
					return
				end
				tbl16[player.UserId] = nil
				if not booleanFlag87 then
					return
				end
			end

			local tableValue76 = {}

			for k, localValue557 in v20.Value, nil, nil do
				if k ~= player then
					tableValue76[k] = localValue557
				end
			end

			if playerOption then
				tableValue76[player] = true
			end

			v20:SetValue(tableValue76)
		end

		local function updateFriendWhitelist2(player)
			if player == localPlayer or player.Parent ~= Players or not featureToggles.AutoWhitelistFriends then
				return
			end
			local ok, result = pcall(localPlayer.IsFriendsWith, localPlayer, player.UserId)

			if ok then
				updateFriendWhitelist(player, result)
			end
		end

		Whitelist:AddDivider("Settings")

		Whitelist:AddToggle("AutoWhitelistFriends", {
			Text = "Auto Whitelist Friends",
			Default = false,
			Tooltip = "Adds your friends to the whitelist",
