				if featureToggles.AutoWhitelistFriends == autoWhitelistFriends then
					return
				end
				featureToggles.AutoWhitelistFriends = autoWhitelistFriends
				api.SetRuntimeConnection("AutoWhitelistFriends", Players.PlayerAdded, autoWhitelistFriends, updateFriendWhitelist2)

				if friendStatusChanged then
					pcall(api.SetRuntimeConnection, "AutoWhitelistStatus", friendStatusChanged, autoWhitelistFriends, function(player, playerArgument)
						if playerArgument == Enum.FriendStatus.Friend or playerArgument == Enum.FriendStatus.NotFriend then
							updateFriendWhitelist(player, playerArgument == Enum.FriendStatus.Friend)
						end
					end)
				end

				if not autoWhitelistFriends then
					return
				end

				task.spawn(function()
					for _, player9 in Players:GetPlayers() do
						if flag11 or not featureToggles.AutoWhitelistFriends then
							return
						end
						updateFriendWhitelist2(player9)
					end
				end)
			end,
		})

