		local function placeControlRelativeToViewport(control)
			local viewportSize = currentCamera.ViewportSize
			local positionVector14 = control.AbsolutePosition + control.AbsoluteSize / 2
			local tableValue77 = {}
			local numericValue214 = positionVector14.X / math.max(viewportSize.X, 1)
			local numericValue215 = positionVector14.Y / math.max(viewportSize.Y, 1)
