		local function placeControlRelativeToViewport2(control, layoutOption, position)
			if not control or not control.Parent then
				return
			end

			if position then
				control.Position = position
			end

			local viewportSize = currentCamera.ViewportSize
			local absoluteSize = control.AbsoluteSize
			local x = control.AbsolutePosition.X
			local y = control.AbsolutePosition.Y

			if typeof(layoutOption) == "table" and typeof(layoutOption[1]) == "number" and typeof(layoutOption[2]) == "number" then
				x = layoutOption[1] * viewportSize.X - absoluteSize.X / 2
				y = layoutOption[2] * viewportSize.Y - absoluteSize.Y / 2
			end

			local numericValue216 = math.clamp(x, 6, math.max(6, viewportSize.X - absoluteSize.X - 6))
			local numericValue217 = math.clamp(y, 6, math.max(6, viewportSize.Y - absoluteSize.Y - 6))
			local absolutePosition

			if control.Parent:IsA("GuiObject") then
				absolutePosition = control.Parent.AbsolutePosition
			else
				absolutePosition = Vector2.zero
			end

			control.Position = UDim2.fromOffset(math.round(numericValue216 - absolutePosition.X + control.AnchorPoint.X * absoluteSize.X), math.round(numericValue217 - absolutePosition.Y + control.AnchorPoint.Y * absoluteSize.Y))
		end

		local function processLocalHelper2(value, layoutOption)
			if not value or not value.Parent or not layoutOption then
