				absoluteSize = viewportSize
			end

			local uiScale = value:FindFirstChildOfClass("UIScale")
			uiScale = uiScale and uiScale.Scale or 1
			local numericValue218 = (absoluteSize.Y * layoutOption.Y.Scale + layoutOption.Y.Offset) * uiScale
			local numericValue219 = math.min(1, (viewportSize.X - 12) / math.max((absoluteSize.X * layoutOption.X.Scale + layoutOption.X.Offset) * uiScale, 1), (viewportSize.Y - 12) / math.max(numericValue218, 1))
			local numericValue220 = layoutOption.Y.Scale * numericValue219
			local round = math.round
			local numericValue221 = layoutOption.Y.Offset * numericValue219
			value.Size = UDim2.new(layoutOption.X.Scale * numericValue219, math.round(layoutOption.X.Offset * numericValue219), numericValue220, round(numericValue221))
		end

